'use strict';
window.CompassRep=(()=>{
 const C=window.COMPASS_CONTEXT,P=window.CompassPlanner,days=['Monday','Tuesday','Wednesday','Thursday','Friday'],colors=['#005c45','#0868ac','#8b4eac','#c16a17','#c33555'];
 let profile=null,formState='SP',plan=null,overrides={},road=null,busy=false,generation=0,map=null,mapDay='all',routingNote='',profileError='';
 const translations=new Map(),offerInputs=new Map();
 let offerPolicy={...window.CompassCommercial.defaults},planningWeights={...window.CompassPriority.defaults};
 try{const saved=JSON.parse(localStorage.getItem('compass.planning-policy.v1')||'null');if(saved)planningWeights=window.CompassPriority.validate(saved);}catch{}
 try{const saved=JSON.parse(localStorage.getItem('compass.offer-policy.v1')||'null');if(saved)offerPolicy=window.CompassCommercial.validatePolicy(saved);}catch{}
 try{const saved=JSON.parse(localStorage.getItem('compass.rep.v2')||'null');if(saved){P.validate(saved,C);profile=saved;}}catch{}
 const base=()=>profile&&C.bases.find(b=>b.id===profile.baseId);
 const contacts=()=>plan?.events.filter(e=>e.type!=='travel')||[];
 const territoryAccounts=()=>D.accounts.filter(a=>!profile||a.state===base().state);
 const localPriority=a=>window.CompassPriority.assess(a,D.asof,planningWeights);
 const candidatePool=()=>territoryAccounts().filter(a=>a.recency<90&&!state.deferred.has(a.id)).sort((a,b)=>localPriority(b).score-localPriority(a).score||a.id.localeCompare(b.id));
 const decision=id=>plan?.decisions.find(d=>d.id===id);
 const schedule=id=>contacts().find(e=>e.id===id);
 const duration=n=>`${Math.floor(n/60)?Math.floor(n/60)+'h ':''}${Math.round(n%60)}m`;
 const modeLabel=e=>e?.type==='visit'?'In-person visit':e?.type==='call'?'Phone call':'Unscheduled';
 const profileSummary=()=>`${title(base().city)}, ${base().state} · ${profile.radius} km reach · ${profile.mode==='car'?'Car':'Public transport'} · ${profile.start}–${profile.end}`;
 const originalShow=show,originalBind=bind,originalAccount=openAccount;
 const actionFor=a=>adviceFor(a);
 rationale=function(a){return actionFor(a).nextStep;};
 show=function(view){if(!profile&&!['profile','model'].includes(view))view='profile';originalShow(view);};
 function rebuild(){if(!profile)return;plan=P.createPlan(D.accounts,C,profile,[...state.selected],overrides,road,planningWeights,D.asof);if(mapDay!=='all'&&!plan.routes.some(r=>r.date===mapDay))mapDay='all';}
 propose=function(){if(!profile)return;state.selected=new Set(candidatePool().slice(0,state.capacity).map(a=>a.id));state.approved=false;rebuild();};
 const selectedCore=selected;
 function renderProfile(){
  const defaults=profile||{baseId:'',visitDays:[1,3],mode:'car',radius:50,start:'09:00',end:'17:00',duration:45};
  if(profile)formState=base().state;
  const states=[...new Set(C.bases.map(b=>b.state))].sort(),locations=C.bases.filter(b=>b.state===formState);
  return `<p class="eyebrow">${profile?'REP SETTINGS':'WELCOME · FIRST-TIME SETUP'}</p><h1>${profile?'Make the week fit.':'Where does your week begin?'}</h1><p class="muted">Choose your base and practical limits. We’ll balance valuable accounts, personal visits and calls.</p><form id="rep-form" class="panel onboarding"><div class="form-grid"><label>Base state<select id="rep-state" required>${states.map(s=>`<option value="${s}" ${s===formState?'selected':''}>${s}</option>`).join('')}</select></label><label>Base city<select id="rep-base" required><option value="">Select your base city</option>${locations.map(b=>`<option value="${b.id}" ${b.id===defaults.baseId?'selected':''}>${esc(title(b.city))}</option>`).join('')}</select></label></div><p class="notice">City centres from the dataset are approximate starting points. Your visit territory is the selected state; your radius further limits personal visits.</p><fieldset><legend>Which days can you visit accounts?</legend><div class="day-choices">${days.map((d,i)=>`<label><input type="checkbox" name="visit-day" value="${i}" ${defaults.visitDays.includes(i)?'checked':''}> ${d}</label>`).join('')}</div><p class="notice">Choose 0–5 days. Calls can use free time on any workday.</p></fieldset><div class="form-grid"><label>Travel by<select id="rep-mode"><option value="car" ${defaults.mode==='car'?'selected':''}>Car</option><option value="transit" ${defaults.mode==='transit'?'selected':''}>Public transport</option></select></label><label>Maximum visit radius (km)<input id="rep-radius" type="number" min="1" max="250" value="${defaults.radius}" required></label><label>Workday starts<input id="rep-start" type="time" min="06:00" max="20:00" value="${defaults.start}" required></label><label>Workday ends<input id="rep-end" type="time" min="08:00" max="22:00" value="${defaults.end}" required></label><label>Visit duration (minutes)<input id="rep-duration" type="number" min="15" max="120" step="5" value="${defaults.duration}" required></label></div><p class="notice">Visits use this editable duration; calls take 30 minutes. Lunch is reserved from 12:00–13:00. Trips start and end at your base. Travel includes a planning buffer.</p>${profile&&state.events.length?'<p class="notice warn-text">Saving changes rebuilds the week and clears the demo agenda and recorded outcomes.</p>':''}<p id="profile-error" class="error" role="alert">${esc(profileError)}</p><button type="submit" class="button primary">${profile?'Save settings and rebuild plan':'Create my weekly plan'}</button></form><p class="notice">Settings are remembered on this browser. Appointments and outcomes remain session-only.</p>`;
 }
 function profileSave(e){
  e.preventDefault();const p={baseId:$('rep-base').value,visitDays:[...document.querySelectorAll('[name="visit-day"]:checked')].map(i=>Number(i.value)),mode:$('rep-mode').value,radius:Number($('rep-radius').value),start:$('rep-start').value,end:$('rep-end').value,duration:Number($('rep-duration').value)};
  try{P.validate(p,C);}catch(err){$('profile-error').textContent=err.message;return;}
  if(state.events.length&&!window.confirm('Rebuild the week and clear the demo agenda, notes and outcomes?'))return;
  profile=p;profileError='';road=null;overrides={};state.events=[];state.deferred.clear();state.territory=base().state;
  try{localStorage.setItem('compass.rep.v2',JSON.stringify(profile));}catch{}
  propose();show('plan');refine();
 }
 function channelCell(a){const d=decision(a.id),e=schedule(a.id);return `<strong class="channel ${e?.type==='visit'?'visit':''}">${modeLabel(e)}</strong><span class="sub">${e?days[D.week.indexOf(e.date)]+' '+e.time+'–'+e.end:''}</span><span class="sub">${d?.distance!==null&&d?.distance!==undefined?Math.round(d.distance)+' km from base':'Location unavailable'}</span><select data-channel="${a.id}" aria-label="Contact method for ${a.id}" ${state.approved||busy?'disabled':''}><option value="auto" ${!overrides[a.id]?'selected':''}>Recommended</option><option value="call" ${overrides[a.id]==='call'?'selected':''}>Prefer call</option><option value="visit" ${overrides[a.id]==='visit'?'selected':''}>Prefer visit</option></select>`;}
 function renderPlanningControls(){
  return `<details class="panel planning-policy"><summary>Priority rules · ×${planningWeights.issueBoost} issue / ×${planningWeights.silencePenalty} long silence · no risk cutoff</summary><p class="notice">Boost once for a recent average rating ≤2/5, known late delivery on a recent purchase, or missing regular product line. The long-silence weight can combine with it. Use 1 for a weight to switch it off. These are planning assumptions, not measured save probabilities.</p><form id="planning-policy-form"><div class="policy-fields"><label>Issue boost<input id="planning-boost" type="number" min="1" max="3" step="0.01" required value="${planningWeights.issueBoost}" ${state.approved||busy?'disabled':''}></label><label>Long-silence weight<input id="planning-penalty" type="number" min="0.1" max="1" step="0.01" required value="${planningWeights.silencePenalty}" ${state.approved||busy?'disabled':''}></label><label>Silence beyond normal order gaps<input id="planning-gaps" type="number" min="2" max="10" step="0.1" required value="${planningWeights.silenceGaps}" ${state.approved||busy?'disabled':''}></label><button class="button small" type="submit" ${state.approved||busy?'disabled':''}>Apply weights & replan</button></div><p id="planning-error" class="error" role="alert"></p>${state.approved?'<p class="notice">Revise the weekly plan to edit weights. Approved appointments stay fixed.</p>':''}</form><p class="notice">Annualised value at risk = monthly exposure ×12. Planning score = annualised value at risk × actionability weight. Exposure shows the stakes; the planning score sets contact priority.</p></details>`;
 }
 function renderOfferLimits(){
  return `<details class="panel offer-policy"><summary>Demo offer limits · ${offerPolicy.openingDiscount}% opening / ${offerPolicy.maxDiscount}% ceiling / ${money(offerPolicy.perOrderCap)} cap</summary><p class="notice">Editable prototype assumptions, not company authorization. Applies to one order only. Account value sets contact priority; discount cost and actual margin determine offer feasibility.</p><form id="offer-policy-form"><div class="policy-fields"><label>Opening discount (%)<input id="policy-opening" type="number" min="0.01" max="100" step="0.01" required value="${offerPolicy.openingDiscount}"></label><label>Discount ceiling (%)<input id="policy-ceiling" type="number" min="0.01" max="100" step="0.01" required value="${offerPolicy.maxDiscount}"></label><label>Cap per order (R$)<input id="policy-cap" type="number" min="0.01" max="1000000" step="0.01" required value="${offerPolicy.perOrderCap}"></label><button class="button small" type="submit">Save demo limits</button></div><p class="error" id="policy-error" role="alert"></p></form></details>`;
 }
 function renderActionCards(list){
  return `<div class="weekly-actions">${list.map((a,i)=>{const action=actionFor(a);return `<article class="contact-card" aria-label="Priority ${i+1}: ${a.id}"><div class="row"><div class="action-account"><span class="priority-number">${i+1}</span><div><button class="account-name" data-account="${a.id}">${a.id}</button><span class="sub">${esc(title(a.city))}, ${a.state}</span></div></div><input type="checkbox" data-select="${a.id}" checked ${state.approved||busy?'disabled':''} aria-label="Select ${a.id}"></div><div class="action-metrics"><div><strong>${pct(a.risk)}</strong><span>90-day inactivity risk</span></div><div><strong>${money(annualValue(a))}</strong><span>Annual account value</span></div><div><strong>${money(annualRisk(a))}</strong><span>Annual value at risk</span></div></div>${priorityHtml(a)}<div class="action-contact">${channelCell(a)}</div><p class="action-label">NEXT BEST ACTION · ${esc(action.basis.toUpperCase())}</p><h3>${esc(action.title)}</h3><p class="action-signal">${esc(action.signal)}</p><div class="cause-summary"><span class="action-label">POSSIBLE CAUSE · ${action.commercial.inputs.driver==='unknown'?'TO CONFIRM':'REP-RECORDED'}</span><strong>${esc(action.causes[0].title)}</strong><span class="sub">${esc(action.causes[0].question)}</span></div><p class="action-next">${esc(action.nextStep)}</p><blockquote class="action-opener"><span class="action-label">YOU CAN SAY</span><p>“${esc(action.talkingPoint)}”</p></blockquote><div class="offer-summary"><span class="action-label">IF THE CONVERSATION DOESN’T RESOLVE IT</span><p>${esc(action.commercial.summary)}</p><span class="sub">${action.commercial.preview.blocked?'Adjust the draft in the full brief.':'Reference discount cost: '+esc(window.CompassCommercial.brl(action.commercial.preview.discount))+' · margin '+(action.commercial.preview.marginKnown?'entered by rep':'unknown')}</span></div><p class="action-goal"><strong>Aim to leave with</strong>${esc(action.successCheck)}</p><div class="action-buttons"><button class="button primary small" data-account="${a.id}" aria-label="Full action brief for ${a.id}">Evidence & negotiation plan</button><button class="button small" data-negotiate="${a.id}" aria-label="Prepare offer for ${a.id}">Prepare offer</button><button class="button small" data-copy-action="${a.id}" aria-label="Copy talking point for ${a.id}">Copy talking point</button></div><details class="outreach-details"><summary>Why this channel & plan options</summary><p>${esc(decision(a.id)?.reason||'No slot available.')}</p><button class="button small" data-defer="${a.id}" ${state.approved||busy?'disabled':''}>Not this week</button></details></article>`;}).join('')}</div>`;
 }
 renderPlan=function(){
  if(!profile)return renderProfile();
  const list=selectedCore(),visits=contacts().filter(e=>e.type==='visit'),calls=contacts().filter(e=>e.type==='call'),pool=candidatePool(),inactive=territoryAccounts().filter(a=>a.recency>=90).length;
  const monitor=pool.filter(a=>!state.selected.has(a.id)).slice(0,4),deferred=territoryAccounts().filter(a=>state.deferred.has(a.id)).sort((a,b)=>Number(state.deferred.has(b.id))-Number(state.deferred.has(a.id))).slice(0,4);
  const first=list.length?actionFor(list[0]):null;
  return `<div class="topline"><div><p class="eyebrow">3–7 SEPTEMBER 2018 · ${esc(title(base().city))}</p><h1>Your week, within reach.</h1><p class="muted">${esc(profileSummary())}</p></div><button class="button primary" id="approve" ${state.approved||busy||!contacts().length||plan?.unscheduled.length?'disabled':''}>${state.approved?'Plan approved':busy?'Checking road times…':`Approve ${contacts().length} contacts`}</button></div><div class="toolbar"><label for="capacity">Contact slots this week</label><input id="capacity" type="number" min="1" max="20" value="${state.capacity}" ${state.approved||busy?'disabled':''}><button class="button small" id="replan" ${busy?'disabled':''}>${state.approved?'Revise weekly plan':'Propose plan'}</button><button class="button small" data-view-extra="profile">Edit rep settings</button><button class="button small" data-view-extra="routes">See visit map</button></div><div class="stats"><div class="stat"><strong>${visits.length}</strong><span>Personal visits on ${plan.routes.length} days</span></div><div class="stat"><strong>${calls.length}</strong><span>Phone conversations</span></div><div class="stat"><strong>${money(list.reduce((s,a)=>s+annualRisk(a),0))}</strong><span>Annualised value at risk in plan</span></div></div><section class="brief action-focus"><div><p class="eyebrow">AGENT BRIEF · ${state.approved?'APPROVED':'PROPOSED'} PLAN</p><h2>${first?'Start with '+list[0].id+'.':'No contacts in this plan.'}</h2>${first?`<p class="focus-next">${esc(first.nextStep)}</p><blockquote class="focus-opener"><span>Suggested opener</span>“${esc(first.talkingPoint)}”</blockquote>`:'<p>No early-warning accounts match your territory and current plan.</p>'}${first?`<p class="focus-offer"><strong>Fallback to prepare:</strong> ${esc(first.commercial.summary)}</p>`:''}<p class="focus-summary">${visits.length} visits · ${calls.length} calls${plan.routes.length?' · '+duration(plan.routes.reduce((total,r)=>total+r.travelMinutes,0))+' reserved for travel':''}${state.approved?' · Ready on your agenda':''}</p></div>${first?`<div class="focus-button"><button class="button lime" data-account="${list[0].id}" aria-label="Full action brief for top priority ${list[0].id}">Full action brief</button></div>`:''}</section>${plan.unscheduled.length?`<p class="error" role="alert">${plan.unscheduled.length} contacts have no available slot. Reduce capacity or change your working hours before approving.</p>`:''}${renderPlanningControls()}${renderOfferLimits()}<section class="action-plan-section"><div class="row"><div><h2>Priorities & next steps</h2><p class="muted">Ranked by annualised value at risk × actionability. No minimum risk cutoff.</p></div><span class="sub">${list.length} / ${state.capacity} contacts · ${pool.length} candidates</span></div>${list.length?renderActionCards(list):'<p class="notice">No eligible contacts in this territory.</p>'}</section><details class="panel planning-notes"><summary>How this week was planned</summary><p>${inactive} accounts are already 90+ days inactive; review them separately for win-back. Visit eligibility uses the top 30% of territory candidates by planning score (${scoreText(plan.threshold)} points or more), then reach and available time. You can override the recommended channel within travel limits.</p><p>${esc(routingNote||plan.source)}. Planning score applies editable actionability weights to annualised value at risk. Annual exposure is 12× monthly exposure at the historical spending rate; the risk prediction remains 90 days. The weights are planning assumptions, not measured save rates.</p></details><div class="grid2"><section class="panel"><h2>Monitor this week</h2><p class="muted">Next accounts by planning score, beyond current contact capacity.</p>${monitor.map(a=>`<div class="row monitor-row"><div><button class="account-name" data-account="${a.id}">${a.id}</button><span class="sub">${pct(a.risk)} risk · ${money(annualRisk(a))}/year at risk</span></div><button class="button small" data-add="${a.id}" ${state.approved||busy||list.length>=state.capacity?'disabled':''}>Add to plan</button></div>`).join('')||'<p>No additional candidates.</p>'}</section><section class="panel"><h2>Deprioritise this week</h2>${deferred.map(a=>`<p><button class="account-name" data-account="${a.id}">${a.id}</button><span class="sub">${'Deferred by rep this week.'}</span></p>`).join('')||'<p class="notice">No accounts deferred.</p>'}<p class="notice">Remote accounts stay in the call plan; coordinate a local rep for visits. No other rep is assigned automatically.</p></section></div>`;
 };
 approve=function(){if(busy||state.approved||!plan)return;if(plan.unscheduled.length){toast('Resolve unscheduled contacts before approval.');return;}state.events=plan.events.map(e=>({...e}));state.approved=true;render();toast(`${contacts().length} contacts approved with travel time reserved.`);};
 async function refine(){
  const token=++generation;road=null;rebuild();routingNote=profile.mode==='transit'?'Public transport estimates: no live timetable or transit route.':'';
  if(profile.mode!=='car'||!profile.visitDays.length||!plan.routes.length){busy=false;render();return;}
  busy=true;render();
  try{const matrix=await P.roadMatrix(D.accounts,C,profile,[...state.selected]);if(token!==generation)return;road=matrix;rebuild();routingNote='Road-based times from OSRM, with 20% time buffer + 10 minutes per leg. No live traffic.';
   for(const r of plan.routes){try{r.geometry=await P.roadGeometry(r,C,base());}catch{r.geometry=null;}if(token!==generation)return;}
  }catch{if(token!==generation)return;road=null;rebuild();routingNote='Driving estimates used: the free road-routing service was unavailable. Distance × 1.35, 35 km/h + 10 minutes per leg.';}
  finally{if(token===generation){busy=false;render();}}
 }
 function renderRoutes(){
  if(!profile)return renderProfile();
  const routes=plan?.routes||[],visible=routes.filter(r=>mapDay==='all'||r.date===mapDay);
  return `<div class="topline"><div><p class="eyebrow">VISIT MAP · ${state.approved?'APPROVED':'PROPOSED'} WEEK</p><h1>Know the next stop.</h1><p class="muted">${esc(profileSummary())}</p></div><button class="button" data-view-extra="agenda">Open agenda</button></div><div class="toolbar"><label for="map-day">Show routes</label><select id="map-day"><option value="all">Whole week</option>${routes.map(r=>`<option value="${r.date}" ${mapDay===r.date?'selected':''}>${days[r.day]} · ${r.visits.length} visits</option>`).join('')}</select>${profile.mode==='car'?`<button class="button small" id="refresh-road" ${busy||state.approved?'disabled':''}>${busy?'Checking road times…':'Refresh road times'}</button>`:''}<span class="sub">Numbered stops · coloured by day · B = base</span></div><div class="route-layout"><div><div id="visit-map" class="visit-map" role="region" aria-label="Map of proposed account visits"></div><p class="notice">Postal-area centres, not exact account addresses. Solid paths are road geometry; dashed lines connect centres when road geometry is unavailable. Public transport paths and times are estimates. Map data © OpenStreetMap contributors.</p><p class="notice">${esc(routingNote||plan.source)}</p></div><div class="route-list">${visible.map(r=>`<section class="panel" style="border-top:4px solid ${colors[r.day]}"><div class="row"><h2>${days[r.day]}</h2><span class="tag">${r.km.toFixed(1)} km · ${duration(r.travelMinutes)}</span></div><p class="sub">${esc(title(base().city))} base · ${esc(r.source)}</p><ol>${r.visits.map(id=>{const a=find(id),e=schedule(id),t=r.events.find(t=>t.destination===id);return `<li><button class="account-name" data-account="${id}">${id}</button><span class="sub">${esc(title(a.city))} · ${e.time}–${e.end}</span><span class="sub">${t.km.toFixed(1)} km / ${duration(t.duration)} from ${t.origin==='BASE'?'base':t.origin}, including buffer</span></li>`;}).join('')}</ol><p class="sub">Return to base by ${r.events.at(-1).end}. Lunch reserved 12:00–13:00.</p></section>`).join('')||'<section class="panel"><h2>No personal visits planned</h2><p>Allocate visit days or increase your radius in rep settings. Phone calls remain on the weekly plan.</p></section>'}</div></div>`;
 }
 function drawMap(){
  if(map){map.remove();map=null;}const node=$('visit-map');if(!node||!profile)return;
  const routes=(plan?.routes||[]).filter(r=>mapDay==='all'||r.date===mapDay);
  if(!window.L){node.innerHTML='<p class="notice">Map unavailable. The ordered stops and distances remain available beside it.</p>';return;}
  map=L.map(node,{scrollWheelZoom:false}).setView([base().lat,base().lng],10);
  L.tileLayer('https://tile.openstreetmap.org/{z}/{x}/{y}.png',{maxZoom:18,attribution:'© <a href="https://www.openstreetmap.org/copyright">OpenStreetMap</a> contributors'}).addTo(map);
  L.circle([base().lat,base().lng],{radius:profile.radius*1000,color:'#004c37',weight:1,fillOpacity:.025,dashArray:'4 7'}).addTo(map);
  const icon=(label,color)=>L.divIcon({className:'compass-pin',html:`<span style="background:${color}">${label}</span>`,iconSize:[30,30],iconAnchor:[15,15]});
  L.marker([base().lat,base().lng],{icon:icon('B','#152d26')}).addTo(map).bindPopup(`${esc(title(base().city))} · base`);
  const bounds=[[base().lat,base().lng]];
  routes.forEach(r=>{const points=[[base().lat,base().lng],...r.visits.map(id=>[C.geo[id].lat,C.geo[id].lng]),[base().lat,base().lng]];bounds.push(...points);const shape=r.geometry?r.geometry.coordinates.map(n=>[n[1],n[0]]):points;L.polyline(shape,{color:colors[r.day],weight:4,opacity:.85,dashArray:r.geometry?undefined:'7 8'}).addTo(map);r.visits.forEach((id,i)=>{const a=find(id),e=schedule(id);L.marker([C.geo[id].lat,C.geo[id].lng],{icon:icon(i+1,colors[r.day]),title:`${days[r.day]} stop ${i+1}: ${id}`}).addTo(map).bindPopup(`<strong>${esc(id)}</strong><br>${days[r.day]} · ${e.time}–${e.end}<br>${esc(title(a.city))}<br>${money(annualRisk(a))}/year at risk`).on('click',()=>openAccount(id));});});
  if(bounds.length>1)map.fitBounds(bounds,{padding:[40,40],maxZoom:13});
 }
 function dayDisplay(date){const items=state.events.filter(e=>e.date===date);const from=Math.max(720,P.minutes(profile.start)),to=Math.min(780,P.minutes(profile.end));if(from<to)items.push({type:'break',from,to,time:P.clock(from),end:P.clock(to)});return items.sort((a,b)=>a.from-b.from);}
 renderAgenda=function(){
  if(!state.events.length)return `<p class="eyebrow">YOUR AGENDA</p><h1>Approve the plan to begin.</h1><section class="panel"><p>Visits, travel blocks and calls are proposed on the weekly brief.</p><button class="button primary" data-view-extra="plan">Review weekly plan</button></section>`;
  const work=state.events.filter(e=>e.type!=='travel');
return `<div class="topline"><div><p class="eyebrow">APPROVED PLAN · 3–7 SEPTEMBER 2018</p><h1>A week that accounts for travel.</h1><p class="muted">${work.filter(e=>e.type==='visit').length} visits · ${work.filter(e=>e.type==='call').length} calls · ${work.filter(e=>e.status!=='Planned').length} outcomes recorded</p></div><button class="button primary" id="export-calendar">Download calendar (.ics)</button></div><p class="notice">Appointments include travel and return to base. Outcomes remain in this session. Nothing is sent to customers or a real calendar.</p><div class="agenda-grid">${D.week.map((date,i)=>`<section class="day"><h3>${days[i]}</h3><span class="sub">${profile.start}–${profile.end}</span>${dayDisplay(date).map(e=>e.type==='break'?`<div class="lunch-block">${e.time}–${e.end} · Lunch / break</div>`:e.type==='travel'?`<div class="travel-block"><time>${e.time}–${e.end}</time><strong>${e.destination==='BASE'?'Return to base':'Travel to '+e.destination}</strong><span>${e.km.toFixed(1)} km · ${duration(e.duration)} incl. buffer</span></div>`:`<article class="event ${e.type==='visit'?'visit-event':''} ${e.status!=='Planned'?'done':''}"><span class="channel ${e.type==='visit'?'visit':''}">${modeLabel(e)}</span><time>${e.time}–${e.end}</time><p><button class="account-name" data-account="${e.id}">${e.id}</button><span class="sub">${esc(title(find(e.id).city))}, ${find(e.id).state}</span></p><p class="sub">${money(annualRisk(find(e.id)))}/year at risk · planning score ${scoreText(priorityFor(find(e.id)).score)}</p><p>${esc(rationale(find(e.id)))}</p><p class="agenda-offer">${esc(actionFor(find(e.id)).commercial.summary)}</p><select data-outcome="${e.id}" aria-label="Outcome for ${e.id}">${['Planned','Contacted','No answer','Issue resolved','Follow-up agreed'].map(s=>`<option ${e.status===s?'selected':''}>${s}</option>`).join('')}</select><input data-note="${e.id}" value="${esc(e.note)}" placeholder="Agreed next step" aria-label="Next step for ${e.id}"><label class="sub" for="follow-${e.id}">Follow-up date</label><input id="follow-${e.id}" data-follow="${e.id}" type="date" min="2018-09-03" value="${e.follow}"><button class="button small" data-account="${e.id}">Open contact brief</button></article>`).join('')||'<p class="notice">No contacts scheduled.</p>'}</section>`).join('')}</div>${work.some(e=>e.follow)?`<section class="panel"><h2>Follow-up queue</h2>${work.filter(e=>e.follow).sort((a,b)=>a.follow.localeCompare(b.follow)).map(e=>`<p><button class="account-name" data-account="${e.id}">${e.id}</button> · ${date(e.follow)}<span class="sub">${esc(e.note||'Confirm the agreed next step')}</span></p>`).join('')}</section>`:''}`;
 };
 function reviewHtml(a){
  const comments=C.reviews[a.id]||[],issues=C.issues[a.id]||[],delivery=C.delivery[a.id];
  return `<section class="review-evidence"><p class="detail-label">DELIVERY & CUSTOMER VOICE</p>${delivery?`<p><strong>${delivery.late} of ${delivery.known} known deliveries were late</strong> on purchases from the last 180 days.${delivery.late?` First observed ${date(delivery.first)}, latest ${date(delivery.last)}.`:''}</p>`:'<p>No usable delivery history in the last 180 days.</p>'}${issues.length?`<p class="sub">Possible issues in safe comments submitted in the last 180 days:</p>${issues.map(i=>`<p><span class="tag warn">${esc(i.tag)}</span> ${i.count} mention${i.count===1?'':'s'} · ${date(i.first)}–${date(i.last)}</p>`).join('')}`:''}<p class="notice">Comments are evidence of reported experiences, not confirmed causes of inactivity. Keyword labels can be wrong. Latest comments are shown alongside an additional negative comment where available; older comments are dated.</p>${comments.map(r=>`<article class="review-card"><div class="row"><strong>${r.score}/5</strong><span class="sub">${date(r.date)} · ${Math.round((new Date(D.asof)-new Date(r.date))/86400000)} days ago</span></div>${r.tags.map(t=>`<span class="tag warn">${esc(t)}</span>`).join('')}<p class="review-original" lang="pt">${esc(r.text)}</p><span class="sub">Portuguese excerpt${r.truncated?' · shortened':''} · contact details / identifiers filtered</span><button class="button small" data-translate="${r.id}">${translations.has(r.id)?'Show English translation':'Translate to English'}</button><p class="translation" id="translation-${r.id}" aria-live="polite">${translations.has(r.id)?'Machine translation · '+esc(translations.get(r.id)):''}</p></article>`).join('')||'<p>No safe written comment available for this account. A missing comment does not mean the buyer was satisfied.</p>'}<p class="notice">Translation sends only the displayed excerpt to MyMemory. Free-service limits apply; the original remains available.</p></section>`;
 }
 openAccount=function(id){
  originalAccount(id);const a=find(id),content=$('detail').querySelector('.dialog-content');
  content.querySelector('.account-action-brief').insertAdjacentHTML('afterend',reviewHtml(a));
  const overdue=Math.max(0,Math.round(a.recency-Math.max(30,2*a.cadence)));
  const location=C.geo[id],reach=profile&&location?P.distance(base(),location):null;
  const geographicNote=decision(id)?.reason||(profile?(a.state!==base().state?'Outside your territory; coordinate the account’s local rep.':reach===null?'Location unavailable; confirm an address before a visit.':`${Math.round(reach)} km from your base. ${reach>profile.radius?'Outside your visit radius; call or coordinate a nearer rep.':'Within your visit radius; eligibility also depends on planning score and available time.'}`):'');
  content.insertAdjacentHTML('beforeend',`<p class="notice">Cadence warning threshold exceeded for approximately ${overdue} days. ${esc(geographicNote)}</p>`);
  $('detail').querySelectorAll('[data-translate]').forEach(b=>b.onclick=()=>translateReview(id,b.dataset.translate));
 };
 async function translateReview(accountId,id){
  const r=C.reviews[accountId]?.find(r=>r.id===id);if(!r)return;
  const output=$('translation-'+id);if(!output)return;
  if(translations.has(id)){output.textContent='Machine translation · MyMemory: '+translations.get(id);return;}
  output.textContent='Translating the displayed excerpt…';const button=$('detail').querySelector(`[data-translate="${id}"]`);if(button)button.disabled=true;
  const chunks=[];let chunk='',count=0;for(const char of r.text){const size=new TextEncoder().encode(char).length;if(count+size>450){chunks.push(chunk);chunk='';count=0;}chunk+=char;count+=size;}if(chunk)chunks.push(chunk);
  try{const translated=[];for(const text of chunks){const controller=new AbortController(),timer=setTimeout(()=>controller.abort(),12000);try{const response=await fetch('https://api.mymemory.translated.net/get?langpair=pt%7Cen&q='+encodeURIComponent(text),{signal:controller.signal});if(!response.ok)throw new Error('Translation unavailable');const j=await response.json();if(j.responseStatus!==200||j.quotaFinished||!j.responseData?.translatedText)throw new Error('Translation limit reached');translated.push(j.responseData.translatedText);}finally{clearTimeout(timer);}}const t=translated.join(' ');translations.set(id,t);if($('translation-'+id))$('translation-'+id).textContent='Machine translation · MyMemory: '+t;
  }catch{if($('translation-'+id))$('translation-'+id).textContent='Translation unavailable or the free quota was reached. The original is shown above; try again later.';}
  finally{if(button)button.disabled=false;}
 }
 calendarText=function(){
  const parts=['BEGIN:VCALENDAR','VERSION:2.0','PRODID:-//Account Compass//Retention Demo//EN','CALSCALE:GREGORIAN'];
  function add(e,follow=false){const day=(follow?e.follow:e.date).replaceAll('-',''),start=(follow?'10:00':e.time).replace(':',''),end=(follow?'10:30':e.end).replace(':','');const travel=e.type==='travel',a=travel?null:find(e.id);const summary=follow?'Follow-up: '+e.id:travel?(e.destination==='BASE'?'Return to base':'Travel to '+e.destination):(e.type==='visit'?'Account visit: ':'Retention call: ')+e.id;const description=travel?`${e.km.toFixed(1)} km. ${e.source}. Includes planning buffer.`:`${evidence(a)}. ${e.reason} Risk ${pct(a.risk)}. Annualised value at risk ${money(annualRisk(a))}/year (12× monthly exposure; 90-day risk). Planning score ${scoreText(priorityFor(a).score)}, weight ×${weightText(priorityFor(a).weight)}. ${priorityFor(a).reasons.join(' ')} ${rationale(a)} Talking point: ${actionFor(a).talkingPoint} Possible causes: ${actionFor(a).causes.map(c=>c.title+' ('+c.status+')').join('; ')}. Offer: ${actionFor(a).commercial.draft||actionFor(a).commercial.summary} Aim: ${actionFor(a).successCheck} Outcome: ${e.status}. ${e.note}`;parts.push('BEGIN:VEVENT',`UID:compass-v2-${e.id}-${follow?'follow':'planned'}-${day}@retention.demo`,'DTSTAMP:20180831T235959Z',`DTSTART:${day}T${start}00`,`DTEND:${day}T${end}00`,`SUMMARY:${icsEscape(summary)}`,`DESCRIPTION:${icsEscape(description)}`,`LOCATION:${icsEscape(travel?e.destination==='BASE'?title(base().city)+' base':e.destination:e.type==='call'?'Phone':title(a.city)+', '+a.state+' (postal-area centre)')}`,'END:VEVENT');}
  state.events.forEach(e=>{add(e);if(e.follow&&e.type!=='travel')add(e,true);});parts.push('END:VCALENDAR');const encoder=new TextEncoder();return parts.map(line=>{let out='',count=0;for(const char of line){const size=encoder.encode(char).length;if(count+size>75){out+='\r\n ';count=1;}out+=char;count+=size;}return out;}).join('\r\n')+'\r\n';
 };
 foot=()=>'<div class="foot">Historical demo · 31 August 2018 · Postal-area accounts · Settings on this browser; agenda and outcomes in this session · <button class="button small ghost" id="reset">Reset demo plan</button></div>';
 bind=function(){
 originalBind();
  // Keep draft next steps as the rep types, including before export or navigation.
  document.querySelectorAll('[data-note]').forEach(el=>el.oninput=()=>{const event=state.events.find(e=>e.id===el.dataset.note);if(event)event.note=el.value;});
  $('agenda-count').textContent=state.events.filter(e=>e.type!=='travel').length;
  document.querySelectorAll('[data-view]').forEach(b=>b.disabled=!profile&&!['profile','model'].includes(b.dataset.view));
  document.querySelectorAll('[data-view-extra]').forEach(b=>b.onclick=()=>show(b.dataset.viewExtra));
  document.querySelectorAll('[data-negotiate]').forEach(b=>b.onclick=()=>{openAccount(b.dataset.negotiate);$('detail').querySelector('.negotiation-plan').scrollIntoView({block:'start'});});
  document.querySelectorAll('[data-copy-action]').forEach(b=>b.onclick=async()=>{try{await navigator.clipboard.writeText(actionFor(find(b.dataset.copyAction)).talkingPoint);toast('Talking point copied.');}catch{toast('Clipboard unavailable. Select and copy the talking point manually.');}});
  if($('rep-state'))$('rep-state').onchange=e=>{formState=e.target.value;const options=C.bases.filter(b=>b.state===formState);$('rep-base').innerHTML='<option value="">Select your base city</option>'+options.map(b=>`<option value="${b.id}">${esc(title(b.city))}</option>`).join('');};
  if($('rep-form'))$('rep-form').onsubmit=profileSave;
  if($('offer-policy-form'))$('offer-policy-form').onsubmit=e=>{e.preventDefault();try{offerPolicy=window.CompassCommercial.validatePolicy({openingDiscount:Number($('policy-opening').value),maxDiscount:Number($('policy-ceiling').value),perOrderCap:Number($('policy-cap').value)});}catch(error){$('policy-error').textContent=error.message;return;}try{localStorage.setItem('compass.offer-policy.v1',JSON.stringify(offerPolicy));}catch{}render();toast('Demo limits saved; review any existing draft notes against the new limits.');};
  if($('planning-policy-form'))$('planning-policy-form').onsubmit=e=>{e.preventDefault();if(state.approved||busy)return;let updated;try{updated=window.CompassPriority.validate({issueBoost:Number($('planning-boost').value),silencePenalty:Number($('planning-penalty').value),silenceGaps:Number($('planning-gaps').value)});}catch(error){$('planning-error').textContent=error.message;return;}planningWeights=updated;try{localStorage.setItem('compass.planning-policy.v1',JSON.stringify(planningWeights));}catch{}propose();refine();toast('Priority weights applied; weekly plan refreshed.');};
  const update=()=>{++generation;busy=false;road=null;routingNote='Travel estimates refreshed after plan changes. Refresh road times on the visit map if needed.';rebuild();render();};
  document.querySelectorAll('[data-select]').forEach(b=>b.onchange=()=>{if(state.approved)return;b.checked?state.selected.add(b.dataset.select):state.selected.delete(b.dataset.select);update();});
  document.querySelectorAll('[data-defer]').forEach(b=>b.onclick=()=>{if(state.approved)return;state.selected.delete(b.dataset.defer);state.deferred.add(b.dataset.defer);update();toast('Deferred for this week.');});
  document.querySelectorAll('[data-add]').forEach(b=>b.onclick=()=>{if(!state.approved&&state.selected.size<state.capacity)state.selected.add(b.dataset.add);update();});
  document.querySelectorAll('[data-channel]').forEach(b=>b.onchange=()=>{if(state.approved)return;b.value==='auto'?delete overrides[b.dataset.channel]:overrides[b.dataset.channel]=b.value;update();});
  if($('capacity'))$('capacity').onchange=e=>{state.capacity=Math.max(1,Math.min(20,Math.floor(Number(e.target.value)||6)));propose();refine();};
  if($('replan'))$('replan').onclick=()=>{if(state.approved&&!window.confirm('Revise the week and clear the demo agenda, notes and outcomes?'))return;state.events=[];state.approved=false;propose();refine();};
  if($('map-day'))$('map-day').onchange=e=>{mapDay=e.target.value;render();};
  if($('refresh-road'))$('refresh-road').onclick=refine;
  $('reset').onclick=()=>{if(window.confirm('Reset the demo plan, appointments and outcomes? Rep settings will be kept.')){++generation;busy=false;state.events=[];state.deferred.clear();state.capacity=6;overrides={};road=null;propose();show('plan');}};
  if(state.view==='routes')drawMap();else if(map){map.remove();map=null;}
 };
 if(profile){state.territory=base().state;propose();state.view='plan';}else state.view='profile';
 // Initialise after CompassRep is attached, so render can call profile/map views.
 queueMicrotask(()=>render());
 return {renderProfile,renderRoutes,getProfile:()=>profile,getPlan:()=>plan,getPlanningPolicy:()=>({...planningWeights}),getOfferPolicy:()=>({...offerPolicy}),getOfferInput:id=>({...offerInputs.get(id)}),setOfferInput:(id,input)=>{if(!find(id))throw new Error('Unknown account');offerInputs.set(id,{...input});},refine};
})();
